/* LaunchWitness design tokens — the single source for colour, type, space, shape and motion.
   Components only use these variables; change the look here. */
:root {
  /* colour */
  --cream: #f5efe4;
  --cream-2: #efe5d4;
  --cream-glow: #f9d9bf; /* warm peach glow in the background gradient */
  --paper: #fffdf8; /* cards on cream */
  --ink: #161614; /* near-black: dark sections, the frame, primary text */
  --ink-2: #222220; /* raised surfaces on dark */
  --ink-line: #3a3a36; /* outlines on dark */
  --on-ink: #f3eee4; /* text on dark */
  --on-ink-muted: #a7a297;
  --text: #1b1b19;
  --muted: #6b665c;
  --line: #e2d9c8; /* hairlines on cream */
  --line-strong: #cfc4af;

  --accent: #dcf06a; /* soft lime: the ONE accent */
  --accent-ink: #1d2205;
  --accent-soft: #f1f8c6;

  --success: #1f8a4c;
  --success-soft: #e3f3e8;
  --warning: #b7790c;
  --warning-soft: #fbf0d7;
  --danger: #c0402b;
  --danger-soft: #fbe7e2;

  --bg-gradient: radial-gradient(120% 80% at 85% 0%, var(--cream-glow) 0%, rgba(249, 217, 191, 0) 55%),
    radial-gradient(90% 70% at 0% 100%, #f2e8c9 0%, rgba(242, 232, 201, 0) 60%),
    linear-gradient(180deg, var(--cream) 0%, var(--cream-2) 100%);

  /* type */
  --font: "Inter Tight", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --fs-xs: 0.78rem;
  --fs-sm: 0.88rem;
  --fs-base: 1rem;
  --fs-md: 1.125rem;
  --fs-lg: clamp(1.3rem, 1.1rem + 0.8vw, 1.6rem);
  --fs-xl: clamp(1.8rem, 1.3rem + 2vw, 2.6rem);
  --fs-2xl: clamp(2.2rem, 1.4rem + 3.4vw, 3.6rem);
  --fs-display: clamp(2.3rem, 0.9rem + 6.6vw, 6.2rem);
  --fw-light: 300;
  --fw-regular: 400;
  --fw-medium: 500;
  --fw-semi: 600;
  --lh-tight: 1.04;
  --lh-snug: 1.25;
  --lh-body: 1.55;
  --tracking-tight: -0.035em;

  /* space (4px base) */
  --s-1: 0.25rem;
  --s-2: 0.5rem;
  --s-3: 0.75rem;
  --s-4: 1rem;
  --s-5: 1.5rem;
  --s-6: 2rem;
107:.card {
111:.card + .card { margin-top: var(--s-4); }
182:.rows { list-style: none; margin: 0; padding: var(--s-2) var(--s-5); }
183:.rows > li { display: flex; gap: var(--s-3); padding: var(--s-4) 0; border-bottom: 1px solid var(--line); }
184:.rows > li:last-child { border-bottom: 0; }
185:.rows .icon { width: 22px; height: 22px; flex: none; margin-top: 1px; }
186:.rows .body { flex: 1; min-width: 0; }
187:.rows .title { font-weight: var(--fw-medium); }
188:.rows .msg { margin-top: 0.2rem; }
189:.rows .when { font-size: var(--fs-xs); margin-top: 0.15rem; }
190:.rows .st-pending .title { color: var(--muted); }
191:.rows .st-failed .msg, .rows .bad .msg { color: var(--danger); }
192:.rows .st-blocked .msg { color: #7a5206; }
193:.rows .row-bad { background: linear-gradient(90deg, var(--danger-soft), transparent 70%); margin: 0 calc(-1 * var(--s-5)); padding-left: var(--s-5); padding-right: var(--s-5); }
223:.badge { display: inline-block; margin-left: 0.5rem; font-size: var(--fs-xs); font-weight: var(--fw-semi); padding: 0.12rem 0.55rem;
225:.doctor {
229:.doctor-label { display: flex; align-items: center; gap: 0.45rem; font-size: var(--fs-xs); text-transform: uppercase; letter-spacing: 0.1em;
231:.doctor-label::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
436:.checks li.needs-you .msg { color: #6d4a06; }
