                        <details className="tech-details">
                          <summary>Technical details</summary>
                          <p className="mono">{r.detail}</p>
                        </details>
                      )}
                    </div>
                  </li>
                );
              })}
            </ul>
          </div>
        ) : null,
      )}
    </>
  );
}

